<template>
  <div class="orders-page"><div class="container page-head"><div><span class="eyebrow">MY ORDERS</span><h1 class="serif">我的定制</h1><p>从定稿到装裱，见证作品诞生的每一步。</p></div><RouterLink to="/create" class="btn btn-primary"><el-icon><Plus /></el-icon>发起新定制</RouterLink></div>
    <div class="container order-tabs"><button v-for="tab in tabs" :key="tab.value" :class="{active:activeTab===tab.value}" @click="activeTab=tab.value">{{ tab.label }}<span v-if="tab.value==='IN_PRODUCTION'&&inProgressCount">{{ inProgressCount }}</span></button></div>
    <div class="container orders-list"><div v-if="loading" v-for="i in 2" :key="i" class="order-skeleton skeleton"></div><template v-else-if="filteredOrders.length"><article v-for="order in filteredOrders" :key="order.id" class="order-card"><div class="order-top"><div><span>订单号 {{ order.order_no }}</span><i></i><span>{{ date(order.created_at) }}</span></div><span class="status" :style="{color:statusMap[order.status]?.color}"><span></span>{{ statusLabel(order.status) }}</span></div><div class="order-body" @click="router.push(`/orders/${order.id}`)"><img :src="mediaUrl(order.media_asset?.url)" alt="定制形象"/><div class="order-info"><h3 class="serif">{{ order.product?.name||'东方形象专属定制' }}</h3><p>{{ order.product?.craft_desc||'画师亲笔创作 · 含基础装裱' }}</p><span v-if="order.artist">创作画师：{{ order.artist.pen_name||order.artist.name }}</span><span v-else>画师匹配：平台根据画种精心安排</span></div><div class="order-price"><span>实付</span><strong>{{ money(order.amount) }}</strong></div><el-icon class="order-arrow"><ArrowRight /></el-icon></div><div class="order-bottom"><div class="mini-progress"><span v-for="(label,i) in ['定稿','交付','创作','装裱','发货']" :key="label" :class="{done:progressStep(order.status)>i,active:progressStep(order.status)===i}"><i></i>{{ label }}</span></div><button class="btn btn-outline btn-sm" @click="router.push(`/orders/${order.id}`)">{{ ['DESIGN_CONFIRM','PENDING_CONFIRM'].includes(order.status)?'确认定稿':'查看进度' }}</button></div></article></template>
      <div v-else class="empty"><span class="seal">绘</span><h2 class="serif">还没有定制作品</h2><p>先生成一幅满意的 AI 形象，再交给画师亲笔创作。</p><RouterLink to="/create" class="btn btn-primary">去创作形象</RouterLink></div>
    </div>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import { orderApi, mediaUrl } from '@/services/api';import { date, money, statusLabel, statusMap } from '@/utils/format';import type { Order } from '@/types'
const router=useRouter(),orders=ref<Order[]>([]),loading=ref(true),activeTab=ref('ALL');const tabs=[{label:'全部订单',value:'ALL'},{label:'待确认',value:'DESIGN_CONFIRM'},{label:'创作中',value:'IN_PRODUCTION'},{label:'已完成',value:'COMPLETED'}]
const inProgressCount=computed(()=>orders.value.filter(o=>['ASSIGNED','IN_PRODUCTION','QUALITY_CHECK'].includes(o.status)).length)
const filteredOrders=computed(()=>{if(activeTab.value==='ALL')return orders.value;if(activeTab.value==='IN_PRODUCTION')return orders.value.filter(o=>['ASSIGNED','IN_PRODUCTION','QUALITY_CHECK'].includes(o.status));return orders.value.filter(o=>o.status===activeTab.value)})
onMounted(async()=>{try{orders.value=await orderApi.list()}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}})
function progressStep(status:string){const step=statusMap[status]?.step||0;return step<=1?0:step===2?1:step===3?2:step===4?3:5}
</script>
<style scoped>
