eight:500}.order-arrow{color:var(--gilt)}.order-bottom{display:flex;justify-content:space-between;align-items:center;padding:14px 20px;background:#f1ecdf}.mini-progress{display:flex;gap:0;width:65%}.mini-progress>span{position:relative;flex:1;display:flex;align-items:center;gap:5px;font-size:8px;color:#aaa79d}.mini-progress>span::after{content:'';height:1px;background:#d9d1c4;flex:1;margin-right:5px}.mini-progress>span:last-child::after{display:none}.mini-progress i{width:6px;height:6px;border-radius:50%;background:#c7c0b4;flex-shrink:0}.mini-progress .done{color:var(--azure)}.mini-progress .done i{background:var(--azure)}.mini-progress .done::after{background:var(--azure)}.mini-progress .active{color:var(--cinnabar)}.mini-progress .active i{background:var(--cinnabar);box-shadow:0 0 0 3px rgba(169,75,60,.12)}.empty{text-align:center;padding:70px 0}.empty .seal{margin:0 auto 22px}.empty h2{font-size:26px}.empty p{color:var(--muted);font-size:12px;margin-bottom:25px}
@media(max-width:768px){.orders-page{padding:35px 0 60px}.page-head h1{font-size:30px}.page-head .btn{padding:0 14px;font-size:11px}.order-tabs{gap:22px;overflow-x:auto}.order-tabs button{flex-shrink:0}.order-top{padding:12px}.order-top>div span:first-child{max-width:155px;overflow:hidden;text-overflow:ellipsis}.order-body{grid-template-columns:75px 1fr auto;gap:12px;padding:14px}.order-body>img{width:75px;height:90px}.order-info h3{font-size:15px}.order-info p{display:none}.order-arrow{display:none}.order-price strong{font-size:16px}.order-bottom{padding:12px}.mini-progress{width:65%}.mini-progress>span{font-size:0;gap:0}.mini-progress .active{font-size:8px}.order-bottom .btn{padding:0 11px}}
